const fs = require('fs');
const ENV = (n) => (typeof $env !== 'undefined' && $env[n]) || '';
const STATE = '/home/node/.n8n/state';
const DRAFTS = STATE + '/drafts';
fs.mkdirSync(DRAFTS, { recursive: true });
const MEDIA_ROOT = '/home/node/materials';
// media paths may arrive as host paths, materials/... relatives or
// bare filenames - resolve them against the read-only mount.
const resolveMedia = (s) => {
  const p = String(s || '');
  if (!p) return null;
  if (fs.existsSync(p)) return p;
  const m = p.match(/(?:^|\/)materials\/(.+)$/);
  if (m) {
    const cand = MEDIA_ROOT + '/' + m[1];
    if (fs.existsSync(cand)) return cand;
  }
  const base = p.split('/').pop();
  for (const dir of [MEDIA_ROOT + '/photos', MEDIA_ROOT]) {
    const cand = dir + '/' + base;
    if (fs.existsSync(cand)) return cand;
  }
  return null;
};
const mimeOf = (p) => (/\.png$/i.test(p) ? 'image/png'
  : /\.webp$/i.test(p) ? 'image/webp' : 'image/jpeg');

let chatId = null;
try { chatId = JSON.parse(fs.readFileSync(STATE + '/tg.json', 'utf8')).chat_id; } catch (e) {}
if (!chatId) {
  return [{ json: { kind: 'msg', ok: false,
    error: 'chat_id unknown - send /start to @shared_person_bot, then run workflow sp-tg-setup' } }];
}

const out = [];
for (const item of $input.all()) {
  const b = item.json.body || item.json;
  const id = b.draft_id || 'd' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  const warnings = Array.isArray(b.warnings) ? b.warnings.map(String)
    : (b.warnings ? [String(b.warnings)] : []);
  const draft = {
    id: id,
    platform: b.platform || 'unknown',
    topic: b.topic || '',
    text: String(b.text || ''),
    image: b.image || b.image_path || '',
    media: Array.isArray(b.media) ? b.media.map(String)
      : (b.media ? [String(b.media)] : []),
    caption_note: String(b.caption_note || ''),
    scope: String(b.scope || ''),
    test: b.test === true,
    warnings: warnings,
    status: 'pending',
    created_at: new Date().toISOString()
  };
  fs.writeFileSync(DRAFTS + '/' + id + '.json', JSON.stringify(draft, null, 2));

  // resolvable media become binary items for the TG SendPhoto node
  // (multipart needs a real HTTP node - Buffer bodies do not survive
  // the task-runner proxy in helpers.httpRequest)
  const mediaFailed = [];
  const mediaOk = [];
  for (const orig of draft.media) {
    const resolved = resolveMedia(orig);
    if (!resolved) { mediaFailed.push(orig); continue; }
    try {
      mediaOk.push({
        path: resolved,
        base64: fs.readFileSync(resolved).toString('base64'),
        mime: mimeOf(resolved),
        fname: resolved.split('/').pop()
      });
    } catch (e) { mediaFailed.push(orig); }
  }

  for (let i = 0; i < mediaOk.length; i++) {
    const m = mediaOk[i];
    out.push({
      json: {
        kind: 'photo', draft_id: id, chat_id: chatId,
        caption: '[DRAFT ' + id + ' | ' + draft.platform + '] media ' +
          (i + 1) + '/' + mediaOk.length + ' - ' + m.fname
      },
      binary: {
        file: { data: m.base64, mimeType: m.mime, fileName: m.fname }
      }
    });
  }
  out.push({
    json: {
      kind: 'msg', draft_id: id, chat_id: chatId,
      media_ok: mediaOk.map((m) => m.path),
      media_failed: mediaFailed
    }
  });
}
return out;

const fs = require('fs');
const ENV = (n) => (typeof $env !== 'undefined' && $env[n]) || '';
const STATE = '/home/node/.n8n/state';
const DRAFTS = STATE + '/drafts';
const token = ENV('TELEGRAM_BOT_TOKEN');
const tg = (method, body) => this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.telegram.org/bot' + token + '/' + method,
  body: body,
  json: true
});

const items = $input.all();
const marker = items.map((i) => i.json || {}).find((j) => j.kind === 'msg') || {};
if (marker.ok === false) return [{ json: marker }];
const chatId = marker.chat_id || '';
const id = marker.draft_id || '';
if (!id || !chatId) return [{ json: { ok: false, error: 'no draft context' } }];
let draft = null;
try { draft = JSON.parse(fs.readFileSync(DRAFTS + '/' + id + '.json', 'utf8')); } catch (e) {}
if (!draft) return [{ json: { ok: false, error: 'draft file missing: ' + id } }];

// photo results = every item except the marker. Successful sendPhoto
// responses carry ok:true; failures arrive as error objects (the HTTP
// node runs with onError=continue). Map results back to paths through
// the resolvable list - item order matches media_ok order.
const resolvable = Array.isArray(marker.media_ok) ? marker.media_ok : [];
const failed = Array.isArray(marker.media_failed) ? marker.media_failed.slice() : [];
let mediaSent = 0;
let seq = 0;
for (const r of items) {
  const resp = r.json || {};
  if (resp.kind === 'msg') continue;
  const idx = seq;
  seq++;
  if (resp.ok === true) { mediaSent++; continue; }
  failed.push(resolvable[idx] || 'photo upload failed');
}
draft.media_sent = mediaSent;

let msg = '[DRAFT ' + id + ' | ' + draft.platform + ']';
if (draft.test === true) {
  msg += '\nTEST POST - will be deleted after verification';
}
if (draft.scope) msg += '\nScope: ' + String(draft.scope).slice(0, 300);
msg += '\n\n' + String(draft.text).slice(0, 3400);
if (draft.warnings && draft.warnings.length) {
  msg += '\n\n[WARNINGS - verifier]\n' +
    draft.warnings.map((w) => '- ' + w).join('\n').slice(0, 700);
}
if (draft.media && draft.media.length) {
  msg += '\n\n[media] ' + mediaSent + '/' + draft.media.length + ' photo(s) attached';
  if (draft.caption_note) msg += ' - ' + String(draft.caption_note).slice(0, 300);
  if (failed.length) msg += '\nattach failed: ' + failed.join(', ').slice(0, 500);
}
const r = await tg('sendMessage', {
  chat_id: chatId,
  text: msg,
  disable_web_page_preview: true,
  reply_markup: {
    inline_keyboard: [[
      { text: 'Approve', callback_data: 'ap:' + id },
      { text: 'Edit', callback_data: 'ed:' + id },
      { text: 'Reject', callback_data: 'rj:' + id }
    ]]
  }
});
if (r && r.ok) draft.message_id = r.result.message_id;
fs.writeFileSync(DRAFTS + '/' + id + '.json', JSON.stringify(draft, null, 2));
return [{ json: { ok: true, draft_id: id, tg_ok: !!(r && r.ok), media_sent: mediaSent } }];

const fs = require('fs');
const ENV = (n) => (typeof $env !== 'undefined' && $env[n]) || '';
const STATE = '/home/node/.n8n/state';
const DRAFTS = STATE + '/drafts';
const PUBLISH = '/home/node/.n8n/queue/publish';
const LOG = '/home/node/.n8n/logs';
for (const d of [STATE, DRAFTS, PUBLISH, PUBLISH + '/done', PUBLISH + '/failed', LOG]) {
  fs.mkdirSync(d, { recursive: true });
}
const token = ENV('TELEGRAM_BOT_TOKEN');
const tg = async (method, body) => {
  try {
    return await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.telegram.org/bot' + token + '/' + method,
      body: body,
      json: true
    });
  } catch (e) { return null; }
};
const log = (rec) => fs.appendFileSync(LOG + '/moderation.jsonl',
  JSON.stringify({ ts: new Date().toISOString(), ...rec }) + '\n');
const loadDraft = (id) => JSON.parse(fs.readFileSync(DRAFTS + '/' + id + '.json', 'utf8'));
const saveDraft = (d) => fs.writeFileSync(DRAFTS + '/' + d.id + '.json', JSON.stringify(d, null, 2));

for (const item of $input.all()) {
  const upd = item.json.body || {};
  // self-heal chat_id from any incoming update
  const chat = (upd.message && upd.message.chat) ||
    (upd.callback_query && upd.callback_query.message && upd.callback_query.message.chat);
  if (chat && chat.id) {
    fs.writeFileSync(STATE + '/tg.json',
      JSON.stringify({ chat_id: chat.id, saved_at: new Date().toISOString() }));
  }

  if (upd.callback_query) {
    const cb = upd.callback_query;
    const data = String(cb.data || '');
    const action = data.slice(0, 2);
    const id = data.slice(3);
    const chatId = cb.message.chat.id;
    const msgId = cb.message.message_id;
    let d = null;
    try { d = loadDraft(id); } catch (e) {}
    if (!d) {
      await tg('answerCallbackQuery', { callback_query_id: cb.id, text: 'draft not found' });
      continue;
    }

    if (action === 'ap') {
      // idempotent approve: a repeated Approve callback (double tap,
      // replayed callback_data) must not rewrite the queue file - the
      // publisher may have already claimed it and a second write would
      // produce a duplicate wall.post
      const alreadyQueued = d.status === 'approved' ||
        ['', '/processing', '/done', '/failed', '/skipped']
          .some((s) => fs.existsSync(PUBLISH + s + '/' + id + '.json'));
      if (alreadyQueued) {
        await tg('answerCallbackQuery', { callback_query_id: cb.id, text: 'already queued' });
        continue;
      }
      d.status = 'approved';
      saveDraft(d);
      // atomic enqueue: tmp name has no .json suffix so the publisher's
      // readdir filter can never claim a half-written file
      const tmp = PUBLISH + '/.' + id + '.tmp';
      fs.writeFileSync(tmp, JSON.stringify({
        id: id, platform: d.platform, text: d.text, image: d.image, media: d.media || [],
        test: d.test === true,
        approved_at: new Date().toISOString()
      }, null, 2));
      fs.renameSync(tmp, PUBLISH + '/' + id + '.json');
      log({ draft: id, action: 'approve' });
      await tg('answerCallbackQuery', { callback_query_id: cb.id, text: 'Queued for publish' });
      await tg('editMessageText', {
        chat_id: chatId, message_id: msgId,
        text: cb.message.text + '\n\n[APPROVED - publish queue]'
      });
    } else if (action === 'rj') {
      d.status = 'rejected';
      saveDraft(d);
      log({ draft: id, action: 'reject' });
      await tg('answerCallbackQuery', { callback_query_id: cb.id, text: 'Rejected' });
      await tg('editMessageText', {
        chat_id: chatId, message_id: msgId,
        text: cb.message.text + '\n\n[REJECTED]'
      });
    } else if (action === 'ed') {
      fs.writeFileSync(STATE + '/pending_edit.json',
        JSON.stringify({ chat_id: chatId, draft_id: id }));
      await tg('answerCallbackQuery', { callback_query_id: cb.id, text: 'Send the corrected text as a reply' });
      await tg('sendMessage', {
        chat_id: chatId,
        text: 'Edit ' + id + ': reply to this chat with the corrected text. It goes back through content-gen for a rewrite.'
      });
    }
    continue;
  }

  if (upd.message) {
    const m = upd.message;
    const chatId = m.chat.id;
    // "post N": resolve item N from the stored digest and send a hype
    // brief to content-gen. Matched before the pending-edit state so an
    // exact command never becomes edit feedback.
    const pm = /^post\s+(\d{1,3})$/i.exec(String(m.text || '').trim());
    if (pm) {
      let digest = {};
      try { digest = JSON.parse(fs.readFileSync(STATE + '/digest.json', 'utf8')); } catch (e) {}
      const days = Object.keys(digest).sort().reverse();
      let it = null;
      for (const day of days) {
        if (digest[day] && digest[day][pm[1]]) { it = digest[day][pm[1]]; break; }
      }
      if (!it) {
        await tg('sendMessage', { chat_id: chatId, text: 'No digest item ' + pm[1] + '.' });
        continue;
      }
      const mt = it.metrics || {};
      const mline = Object.keys(mt).map((k) => k + ' ' + mt[k]).join(', ');
      const facts = [
        'Title: ' + (it.title || ''),
        'Source: ' + (it.source || ''),
        'Published: ' + (it.published || ''),
        mline ? 'Metrics: ' + mline : '',
        it.hype != null ? 'Hype score: ' + it.hype + '/100' : '',
        it.angle ? 'Angle: ' + it.angle : '',
        it.summary ? 'Summary: ' + it.summary : '',
        it.url ? 'Link: ' + it.url : ''
      ].filter(Boolean).join('\n');
      const brief = {
        source_type: 'hype', topic: it.title || '',
        facts: facts, links: it.url ? [it.url] : [],
        scope: 'commentary on a third-party post; do not claim it as own work',
        accents: it.angle ? [it.angle] : []
      };
      log({ action: 'post_n', n: pm[1], item: it.id || null });
      try {
        await this.helpers.httpRequest({
          method: 'POST',
          url: 'http://127.0.0.1:5780/webhook/content-gen',
          body: {
            platform: 'all', topic: brief.topic, source_type: 'hype',
            scope: brief.scope, accents: brief.accents, links: brief.links,
            context: JSON.stringify(brief, null, 2)
          },
          json: true, timeout: 300000
        });
        await tg('sendMessage', {
          chat_id: chatId,
          text: 'Item ' + pm[1] + ' sent to content-gen - drafts will arrive here for moderation.'
        });
      } catch (e) {
        await tg('sendMessage', { chat_id: chatId, text: 'Generation failed: ' + String(e).slice(0, 200) });
      }
      continue;
    }
    let pend = null;
    try { pend = JSON.parse(fs.readFileSync(STATE + '/pending_edit.json', 'utf8')); } catch (e) {}
    if (pend && pend.chat_id === chatId && m.text && !m.text.startsWith('/')) {
      let d = null;
      try { d = loadDraft(pend.draft_id); } catch (e) {}
      fs.unlinkSync(STATE + '/pending_edit.json');
      if (!d) {
        await tg('sendMessage', { chat_id: chatId, text: 'Draft file missing - edit discarded.' });
        continue;
      }
      log({ draft: d.id, action: 'edit', feedback: m.text.slice(0, 500) });
      try {
        await this.helpers.httpRequest({
          method: 'POST',
          url: 'http://127.0.0.1:5780/webhook/content-gen',
          body: {
            mode: 'rewrite', draft_id: d.id, platform: d.platform, topic: d.topic,
            feedback: m.text, context: 'Previous draft:\n' + d.text
          },
          json: true, timeout: 300000
        });
        await tg('sendMessage', {
          chat_id: chatId,
          text: 'Draft ' + d.id + ' sent for rewrite - the new version will arrive here for moderation.'
        });
      } catch (e) {
        await tg('sendMessage', { chat_id: chatId, text: 'Rewrite failed: ' + String(e).slice(0, 200) });
      }
    } else {
      await tg('sendMessage', { chat_id: chatId, text: 'Bot live. Drafts for moderation arrive here automatically.' });
    }
  }
}
return [{ json: { ok: true } }];
